function criarLoja(id, comandos, titulo, bullets, precoDe, precoAte, produtos, extra, ficheiro, canais) {
    return {
        id,
        comandos,
        canais: canais || [],
        ficheiro: ficheiro || FICHEIRO_BANNER_LOJA,
        texto: (
            `## ${titulo}\n` +
            bullets.map((b) => `• ${b}`).join('\n') +
            (extra ? `\n\n${extra}` : '') +
            '\n\n```ansi\n\u001b[2;32m⚡ Entrega Automática!\u001b[0m\n```'
        ),
        rodape: `Preço: **De ${precoDe} a ${precoAte}**\nClique no botão **"Comprar"**`,
        tituloClassico: titulo,
        produtos
    };
}

